import { categoryLabel } from "./markets.js";
import { scoreLead } from "./scoring.js";
import type { Lead } from "./leads.js";

/**
 * Facts for writing a proposal, as plain English, built from a saved lead by fixed templates.
 *
 * The Proposal Writer agent gets these facts and writes the proposal text; nothing here is generated by a model and nothing in it
 * comes from website content (the lead's fields were cleaned when they were saved). There is no price: the owner decides that.
 * A proposal is only ever a draft for the owner to approve. Nothing here sends anything.
 */
const SERVICE_FOR: [needle: string, service: string][] = [
  ["secure connection", "Secure the website with HTTPS, so browsers stop showing a \"not secure\" warning."],
  ["security certificate", "Fix or renew the website's security certificate."],
  ["works on phones", "Make the website work well on phones, where most visitors are."],
  ["easy to contact", "Add clear ways to get in touch: phone, email and a WhatsApp button."],
  ["looks up to date", "Refresh the content and design so the site looks looked-after."],
  ["modern page build", "Replace outdated parts of the site with a modern layout."],
  ["loads quickly", "Make the website load faster."],
  ["page title", "Improve the page title so the business is easier to find in search."],
  ["search description", "Add a search description so search results explain what the business offers."],
];

const NEW_SITE = "Build a simple, mobile-friendly website with the business's contact details and a WhatsApp button.";

function problemsOf(summary: string): string[] {
  const m = /^Problems: (.*?)\.(?: Low confidence.*)?$/.exec(summary.trim());
  return m ? m[1]!.split(";").map((s) => s.trim().toLowerCase()).filter(Boolean) : [];
}

export function suggestedServices(l: Lead): string[] {
  if (l.website_state === "confirmed_none" || l.website_state === "none_listed") return [NEW_SITE];
  if (l.website_state !== "audited") return [];
  if (/^Placeholder or parked page/.test(l.audit_summary)) return [NEW_SITE];
  const problems = problemsOf(l.audit_summary);
  return SERVICE_FOR.filter(([needle]) => problems.some((p) => p.includes(needle))).map(([, s]) => s);
}

export function websiteSituation(l: Lead): string {
  switch (l.website_state) {
    case "confirmed_none":
      return "The owner has confirmed that this business has no website.";
    case "none_listed":
      return "No website is listed in public data. This is UNVERIFIED: check by hand that there really is none before saying so.";
    case "not_audited":
      return "A website address is listed but it has not been checked yet.";
    case "audit_failed":
      return `The website could not be checked (${l.audit_failure.replace(/_/g, " ")}). Do NOT describe the website as poor or as missing: it is simply unchecked. Verify it by hand.`;
    case "audited":
      return /^Placeholder or parked page/.test(l.audit_summary)
        ? "The website address leads to a placeholder or parked page, not a real website."
        : `The website was checked and scored ${l.audit_score ?? "?"} out of 100${l.audit_confidence === "low" ? " (low confidence: part of the page could not be judged)" : ""}. ${l.audit_summary}`;
  }
}

export function proposalFacts(l: Lead): string {
  const s = scoreLead(l);
  const services = suggestedServices(l);
  const verified = l.website_state === "audited" || l.website_state === "confirmed_none";
  return [
    `Business: ${l.business_name}${l.business_name_ar ? ` (${l.business_name_ar})` : ""}`,
    `Type: ${categoryLabel(l.category)}. Place: ${[l.city, l.region].filter(Boolean).join(", ") || "United Arab Emirates"}.`,
    `Website: ${websiteSituation(l)}`,
    services.length ? `Suggested services, taken from the findings:\n${services.map((x) => `- ${x}`).join("\n")}` : "Suggested services: none yet. The website has to be checked first.",
    `Lead priority: ${s.priority} (score ${s.score} of 100). ${s.reasons}`,
    `Status in the leads file: ${l.status}.`,
    "How to write the proposal: write it in English, in a friendly and honest tone, and keep it short. Use only the facts above and nothing else. Do not state a price: the owner decides that. " +
      (verified ? "" : "The website facts are not verified, so do not state them as certain. ") +
      "The proposal is a DRAFT for the owner to approve. Do not send it, and do not contact the business.",
  ].join("\n");
}
